package com.dunerealms.ban;
import com.google.gson.JsonParser;
import net.kyori.adventure.text.Component;
import net.luckperms.api.LuckPermsProvider;
import org.bukkit.*;
import org.bukkit.ban.ProfileBanList;
import org.bukkit.command.*;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.player.AsyncPlayerPreLoginEvent;
import org.bukkit.plugin.java.JavaPlugin;
import java.net.URI;
import java.net.http.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Supplier;

public final class DuneBan extends JavaPlugin implements Listener,CommandExecutor,TabCompleter {
 public record Result(boolean ok,String message){}
 public record BanView(UUID uuid,String name,String reason,String created,String expires,String source){}
 private final ExecutorService worker=Executors.newFixedThreadPool(2,r->{Thread t=new Thread(r,"DuneBan-storage");t.setDaemon(true);return t;});
 private final Set<UUID> busy=ConcurrentHashMap.newKeySet();
 private final Map<UUID,String> verifiedNames=new ConcurrentHashMap<>();
 private final AtomicBoolean polling=new AtomicBoolean();
 private volatile BanStore store;private volatile boolean ready;private String source;private Thread serverThread;
 private static final Component UNAVAILABLE=Component.text("DuneRealms moderation verification is temporarily unavailable. Please reconnect shortly.");
 static boolean validServer(String id){return id!=null&&Set.of("arrakis","kaitain","giedi_prime","caladan","sigma_draconis_iv","lobby").contains(id);}
 @Override public void onEnable(){
  serverThread=Thread.currentThread();saveDefaultConfig();source=getConfig().getString("server-id","arrakis");
  if(!validServer(source))throw new IllegalStateException("Invalid fixed server-id");
  getServer().getPluginManager().registerEvents(this,this);
  for(String name:List.of("duneban","duneunban")){getCommand(name).setExecutor(this);getCommand(name).setTabCompleter(this);}
  var config=getConfig();var core=getServer().getPluginManager().getPlugin("DuneCore");
  String url=config.getString("database.jdbc-url","");String user=config.getString("database.username","");String password=config.getString("database.password","");
  if(url.isBlank()&&core instanceof JavaPlugin plugin){url=plugin.getConfig().getString("database.jdbc-url","");user=plugin.getConfig().getString("database.username","");password=plugin.getConfig().getString("database.password","");}
  try{store=new BanStore(url,user,password);worker.execute(()->{try{store.initialize();ready=true;getLogger().info("Network ban storage ready.");}catch(Exception e){getLogger().severe("Network ban storage unavailable. Global verification remains fail-closed.");}});}catch(Exception e){getLogger().severe("Private database settings required. Global verification remains fail-closed.");}
  getServer().getScheduler().runTaskTimer(this,()->pollOnline(),40,40);
 }
 @Override public void onDisable(){ready=false;worker.shutdownNow();}
 private <T> CompletableFuture<T> main(Supplier<T> operation){CompletableFuture<T> f=new CompletableFuture<>();Runnable r=()->{try{if(!isEnabled())throw new IllegalStateException("Plugin unavailable");f.complete(operation.get());}catch(Throwable e){f.completeExceptionally(e);}};if(Thread.currentThread()==serverThread)r.run();else getServer().getScheduler().runTask(this,r);return f;}
 private static String node(String action,String scope){return "dune."+action+"."+scope;}
 private void actor(Player actor,String action,String scope){if(actor==null||!actor.isOnline()||getServer().getPlayer(actor.getUniqueId())!=actor||!actor.hasPermission(node(action,scope)))throw new IllegalArgumentException("Current permission required: "+node(action,scope));}
 private void guard(Player actor,UUID target,String scope,boolean offlineProtected){actor(actor,"ban",scope);Player online=getServer().getPlayer(target);BanRules.target(actor.getUniqueId(),target,getServer().getOfflinePlayer(target).isOp(),offlineProtected||(online!=null&&(online.hasPermission("dune.ban.protected")||online.hasPermission("dune.moderation.protected"))));}
 private CompletableFuture<Boolean> protectedOffline(UUID target){return main(()->getServer().getPlayer(target)!=null).thenCompose(online->{if(online)return CompletableFuture.completedFuture(false);return CompletableFuture.supplyAsync(()->{try{var user=LuckPermsProvider.get().getUserManager().loadUser(target).get(5,TimeUnit.SECONDS);var data=user.getCachedData().getPermissionData();return data.checkPermission("dune.ban.protected").asBoolean()||data.checkPermission("dune.moderation.protected").asBoolean();}catch(Exception e){throw new CompletionException(new IllegalArgumentException("Offline protection could not be verified. No punishment was applied."));}},worker);});}
 private static Result failure(Throwable error){Throwable e=error;while(e.getCause()!=null&&(e instanceof CompletionException||e instanceof ExecutionException))e=e.getCause();return new Result(false,e instanceof IllegalArgumentException?e.getMessage():"The action could not be confirmed. Refresh the ban list before retrying.");}
 public CompletableFuture<Result> banScoped(Player actor,UUID target,String reason,Duration duration,String scope){
  try{BanRules.scope(scope);reason=BanRules.reason(reason);BanRules.duration(duration);if(actor==null||target==null)throw new IllegalArgumentException("Choose a player.");}catch(Exception e){return CompletableFuture.completedFuture(failure(e));}
  if(!busy.add(actor.getUniqueId()))return CompletableFuture.completedFuture(new Result(false,"Another moderation action is pending."));
  final String finalReason=reason;
  return protectedOffline(target).thenCompose(protectedTarget->main(()->{guard(actor,target,scope,protectedTarget);String name=verifiedName(target);if(scope.equals("local")&&name==null)throw new IllegalArgumentException("Local bans require a verified player name. Select a known profile or use an exact Java username.");if(name==null)name=target.toString();
   if(scope.equals("local")){ProfileBanList list=getServer().getBanList(BanList.Type.PROFILE);Player actual=getServer().getPlayer(target);var profile=actual!=null?actual.getPlayerProfile():getServer().createPlayerProfile(target,name);if(profile==null)throw new IllegalArgumentException("Verified player profile unavailable.");if(list.getBanEntry(profile)!=null)throw new IllegalArgumentException("A local ban already exists. Refresh its record.");Instant until=duration==null?null:Instant.now().plus(duration);list.addBan(profile,finalReason,until,actor.getName()+" [DuneBan:"+source+"]");if(!list.isBanned(profile))throw new IllegalStateException("Local ban unconfirmed");Player player=getServer().getPlayer(target);if(player!=null)player.kick(Component.text("DuneRealms local ban: "+finalReason+"\nScope: "+source+"\nAppeal: https://support.dunerealms.com/appeal.php"));return name;}
   if(!ready||store==null)throw new IllegalArgumentException("Network ban storage is unavailable. No ban was applied.");return name;
  })).thenCompose(name->{if(scope.equals("local"))return CompletableFuture.completedFuture(new Result(true,"Local ban confirmed on "+source+"."));return CompletableFuture.supplyAsync(()->{try{main(()->{actor(actor,"ban",scope);return null;}).join();BanRecord record=store.add(target,name,actor.getUniqueId(),actor.getName(),finalReason,BanRules.duration(duration),source);return new Result(true,"Network ban recorded. Reference: "+record.id());}catch(Exception e){throw new CompletionException(e);}},worker);}).exceptionally(DuneBan::failure).whenComplete((result,error)->busy.remove(actor.getUniqueId()));
 }
 public CompletableFuture<List<BanView>> listBans(Player actor,String scope){
  try{BanRules.scope(scope);}catch(Exception e){return CompletableFuture.failedFuture(e);}
  return main(()->{actor(actor,"unban",scope);if(scope.equals("global")){if(!ready)throw new IllegalStateException("Storage unavailable");return null;}ProfileBanList list=getServer().getBanList(BanList.Type.PROFILE);List<BanView> rows=new ArrayList<>();for(org.bukkit.BanEntry<?> entry:list.getBanEntries()){if(!(entry.getBanTarget() instanceof org.bukkit.profile.PlayerProfile profile))continue;UUID id=profile.getUniqueId();if(id==null)continue;String name=profile.getName();rows.add(new BanView(id,name==null?id.toString():name,entry.getReason(),entry.getCreated().toInstant().toString(),entry.getExpiration()==null?"forever":entry.getExpiration().toInstant().toString(),source));}return rows;}).thenCompose(local->{if(local!=null)return CompletableFuture.completedFuture(local);return CompletableFuture.supplyAsync(()->{try{return store.active().stream().map(b->new BanView(b.player(),b.name(),b.reason(),b.createdText(),b.expiresText(),"network")).toList();}catch(Exception e){throw new CompletionException(e);}},worker);}).thenCompose(rows->main(()->{actor(actor,"unban",scope);return rows;}));
 }
 public CompletableFuture<Result> unbanScoped(Player actor,UUID target,String expectedCreated,String reason,String scope){
  final long created;try{BanRules.scope(scope);BanRules.reason(reason);created=BanRules.created(expectedCreated);if(actor==null||target==null)throw new IllegalArgumentException("Choose a player.");}catch(Exception e){return CompletableFuture.completedFuture(failure(e));}
  if(!busy.add(actor.getUniqueId()))return CompletableFuture.completedFuture(new Result(false,"Another moderation action is pending."));
  return main(()->{actor(actor,"unban",scope);if(scope.equals("global")){if(!ready)throw new IllegalStateException("Storage unavailable");return false;}ProfileBanList list=getServer().getBanList(BanList.Type.PROFILE);var profile=getServer().createPlayerProfile(target);var entry=list.getBanEntry(profile);if(entry==null)throw new IllegalArgumentException("That local ban is no longer present. Refresh first.");if(entry.getCreated().getTime()!=created)throw new IllegalArgumentException("The local ban changed. Refresh before removing it.");list.pardon(profile);if(list.isBanned(profile))throw new IllegalStateException("Local removal unconfirmed");return true;}).thenCompose(local->{if(local)return CompletableFuture.completedFuture(new Result(true,"Exact local ban removed."));return CompletableFuture.supplyAsync(()->{try{main(()->{actor(actor,"unban",scope);return null;}).join();boolean removed=store.remove(target,created,actor.getUniqueId()+":"+actor.getName(),reason);return new Result(removed,removed?"Exact network ban removed.":"No current network ban matched. Refresh first.");}catch(Exception e){throw new CompletionException(e);}},worker);}).exceptionally(DuneBan::failure).whenComplete((result,error)->busy.remove(actor.getUniqueId()));
 }
 private String verifiedName(UUID target){String name=getServer().getOfflinePlayer(target).getName();if(validName(name))return name;if(verifiedNames!=null){name=verifiedNames.get(target);if(validName(name))return name;}try{var user=LuckPermsProvider.get().getUserManager().getUser(target);if(user!=null&&validName(user.getUsername()))return user.getUsername();}catch(Exception unavailable){}return null;}
 private static boolean validName(String value){return value!=null&&value.matches("[A-Za-z0-9_.]{1,40}");}
 private CompletableFuture<UUID> resolve(String name){Player online=getServer().getPlayerExact(name);if(online!=null)return CompletableFuture.completedFuture(online.getUniqueId());try{UUID explicit=UUID.fromString(name);if(explicit.toString().equalsIgnoreCase(name)){if(explicit.equals(new UUID(0,0)))return CompletableFuture.failedFuture(new IllegalArgumentException("Choose a nonzero Minecraft UUID."));return CompletableFuture.completedFuture(explicit);}}catch(IllegalArgumentException notUuid){}try{BanRules.username(name);}catch(Exception e){return CompletableFuture.failedFuture(e);}OfflinePlayer cached=getServer().getOfflinePlayerIfCached(name);if(cached!=null&&cached.getName()!=null&&cached.getName().equalsIgnoreCase(name))return CompletableFuture.completedFuture(cached.getUniqueId());
  return CompletableFuture.supplyAsync(()->{try{var request=HttpRequest.newBuilder(URI.create("https://api.mojang.com/users/profiles/minecraft/"+name)).timeout(Duration.ofSeconds(5)).GET().build();var response=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(3)).followRedirects(HttpClient.Redirect.NEVER).build().send(request,HttpResponse.BodyHandlers.ofString());if(response.statusCode()!=200||response.body().length()>4096)throw new IllegalArgumentException();var json=JsonParser.parseString(response.body()).getAsJsonObject();String id=json.get("id").getAsString();if(!id.matches("[0-9a-fA-F]{32}")||!json.get("name").getAsString().equalsIgnoreCase(name))throw new IllegalArgumentException();UUID resolved=UUID.fromString(id.substring(0,8)+"-"+id.substring(8,12)+"-"+id.substring(12,16)+"-"+id.substring(16,20)+"-"+id.substring(20));if(verifiedNames!=null)verifiedNames.put(resolved,json.get("name").getAsString());return resolved;}catch(Exception e){throw new CompletionException(new IllegalArgumentException("Verified username lookup failed. No offline UUID was guessed."));}},worker);
 }
 @Override public boolean onCommand(CommandSender sender,Command command,String label,String[] args){if(!(sender instanceof Player actor)){sender.sendMessage("Use the authenticated staff game account or the private appeal provider.");return true;}boolean unban=command.getName().equals("duneunban");if(args.length==0){boolean permitted=java.util.stream.Stream.of("dune.ban.local","dune.ban.global","dune.unban.local","dune.unban.global").anyMatch(actor::hasPermission);if(!permitted||!actor.isOnline()||getServer().getPlayer(actor.getUniqueId())!=actor){actor.sendMessage("A current scoped moderation permission is required.");return true;}var core=getServer().getPluginManager().getPlugin("DuneCore");if(core==null||!core.isEnabled()||!actor.performCommand("dunecore:dune admin"))actor.sendMessage("The staff navigator is unavailable. Use the complete scoped command or retry shortly.");return true;}if(args.length<(unban?4:3)){sender.sendMessage(unban?"/duneunban <local|global> <user> <created-ISO> <reason>":"/duneban <local|global> <user> <reason>");return true;}try{BanRules.scope(args[0]);actor(actor,unban?"unban":"ban",args[0]);String reason=String.join(" ",Arrays.copyOfRange(args,unban?3:2,args.length));BanRules.reason(reason);resolve(args[1]).thenCompose(id->unban?unbanScoped(actor,id,args[2],reason,args[0]):banScoped(actor,id,reason,null,args[0])).exceptionally(DuneBan::failure).thenAccept(result->main(()->{if(actor.isOnline())actor.sendMessage(Component.text(result.message()));return null;}));}catch(Exception e){actor.sendMessage(Component.text(failure(e).message()));}return true;}
 @Override public List<String> onTabComplete(CommandSender sender,Command command,String label,String[] args){if(args.length==1)return List.of("local","global").stream().filter(s->sender.hasPermission(node(command.getName().equals("duneunban")?"unban":"ban",s))&&s.startsWith(args[0])).toList();if(args.length==2)return getServer().getOnlinePlayers().stream().map(Player::getName).filter(s->s.toLowerCase(Locale.ROOT).startsWith(args[1].toLowerCase(Locale.ROOT))).toList();return List.of();}
 @EventHandler(priority=EventPriority.HIGHEST) public void login(AsyncPlayerPreLoginEvent event){if(event.getLoginResult()!=AsyncPlayerPreLoginEvent.Result.ALLOWED)return;try{if(!ready||store==null)throw new IllegalStateException();BanRecord ban=store.find(event.getUniqueId());if(ban!=null)event.disallow(AsyncPlayerPreLoginEvent.Result.KICK_BANNED,Component.text(ban.notice()));}catch(Exception e){event.disallow(AsyncPlayerPreLoginEvent.Result.KICK_OTHER,UNAVAILABLE);}}
 private void pollOnline(){if(!polling.compareAndSet(false,true))return;Map<UUID,Player> online=new HashMap<>();for(Player player:getServer().getOnlinePlayers())online.put(player.getUniqueId(),player);if(online.isEmpty()){polling.set(false);return;}CompletableFuture.supplyAsync(()->{try{if(!ready||store==null)throw new IllegalStateException();return store.online(online.keySet());}catch(Exception e){throw new CompletionException(e);}},worker).whenComplete((bans,error)->{main(()->{Map<UUID,BanRecord> records=new HashMap<>();if(bans!=null)for(BanRecord ban:bans)records.put(ban.player(),ban);for(var entry:online.entrySet()){Player player=entry.getValue();if(getServer().getPlayer(entry.getKey())!=player)continue;BanRecord ban=records.get(entry.getKey());if(error!=null)player.kick(UNAVAILABLE);else if(ban!=null)player.kick(Component.text(ban.notice()));}return null;}).whenComplete((ignored,ignoredError)->polling.set(false));});}
}



